<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>grok-4.7 — 신호의 장</title>
<style>
  :root { --bg:#07080d; --ink:#f4f1ea; --dim:#b7b2c8; --accent:#7ee0c6; }
  * { box-sizing:border-box; }
  html,body { margin:0; height:100%; background:var(--bg); color:var(--ink);
    font-family:system-ui,-apple-system,sans-serif; }
  body { overflow:hidden; }
  canvas { position:fixed; inset:0; width:100%; height:100%; display:block; }
  header { position:fixed; top:0; left:0; right:0; padding:1.2rem 1.4rem;
    display:flex; justify-content:space-between; align-items:flex-start;
    pointer-events:none; z-index:2; }
  h1 { margin:0; font-size:clamp(1.6rem,4vw,2.6rem); letter-spacing:.04em; font-weight:650; }
  h1 span { color:var(--accent); }
  p { margin:.3rem 0 0; color:var(--dim); font-size:clamp(.85rem,2vw,1rem); max-width:36ch; }
  aside { position:fixed; bottom:0; left:0; right:0; padding:1rem 1.4rem 1.2rem;
    color:var(--dim); font-size:.9rem; z-index:2; display:flex; gap:1.2rem;
    flex-wrap:wrap; }
  button { pointer-events:auto; background:transparent; color:var(--ink);
    border:1px solid var(--dim); border-radius:999px; padding:.55rem 1rem;
    font-size:1rem; cursor:pointer; }
  button:focus-visible, :focus-visible { outline:3px solid var(--accent); outline-offset:3px; }
  @media (prefers-reduced-motion: reduce) { canvas { display:none; } }
</style>
</head>
<body>
<canvas id="field" aria-hidden="true"></canvas>
<header>
  <div>
    <h1>grok-<span>4.7</span></h1>
    <p>생각이 입자로 흩어지고 다시 모이는 장. 손끝과 키보드로 신호를 흔들어 보세요.</p>
  </div>
</header>
<aside>
  <button id="burst" type="button">신호 보내기 (Space)</button>
  <span>방향키로 흐름을 바꾸기 · 클릭으로 끌기</span>
</aside>
<script>
const c = document.getElementById('field');
const ctx = c.getContext('2d');
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
let w, h, dpr, mx = 0, my = 0, flow = 0, pulses = [];
const N = reduce ? 40 : 140;
const parts = Array.from({length:N}, () => spawn());
function spawn() {
  return { a: Math.random()*6.28, r: 40+Math.random()*Math.min(innerWidth,innerHeight)*.42,
    s: .2+Math.random()*.8, o: .25+Math.random()*.7 };
}
function resize() {
  dpr = Math.min(devicePixelRatio||1, 2);
  w = c.width = innerWidth*dpr; h = c.height = innerHeight*dpr;
  c.style.width = innerWidth+'px'; c.style.height = innerHeight+'px';
}
addEventListener('resize', resize); resize();
addEventListener('pointermove', e => { mx = e.clientX*dpr; my = e.clientY*dpr; });
addEventListener('pointerdown', e => pulses.push({x:e.clientX*dpr, y:e.clientY*dpr, t:1}));
addEventListener('keydown', e => {
  if (e.key==='ArrowLeft') flow -= .4;
  if (e.key==='ArrowRight') flow += .4;
  if (e.key==='ArrowUp') flow -= .2;
  if (e.key==='ArrowDown') flow += .2;
  if (e.key===' ') { e.preventDefault(); burst(); }
});
document.getElementById('burst').onclick = burst;
function burst(){ pulses.push({x:w/2, y:h/2, t:1}); }
function frame(){
  ctx.fillStyle = 'rgba(7,8,13,.18)'; ctx.fillRect(0,0,w,h);
  const cx = w/2, cy = h/2;
  parts.forEach(p => {
    if (!reduce) p.a += (p.s*.004) + flow*.002;
    const px = cx + Math.cos(p.a)*p.r*dpr*.5;
    const py = cy + Math.sin(p.a*1.3)*p.r*dpr*.32;
    const dx = (mx||cx) - px, dy = (my||cy) - py;
    const pull = Math.max(0, 1 - Math.hypot(dx,dy)/(280*dpr));
    ctx.beginPath();
    ctx.fillStyle = `rgba(126,224,198,${p.o*(.4+pull)})`;
    ctx.arc(px + dx*pull*.15, py + dy*pull*.15, (1.4+pull*3)*dpr, 0, 6.28);
    ctx.fill();
  });
  pulses = pulses.filter(p => p.t>0);
  pulses.forEach(p => {
    ctx.strokeStyle = `rgba(244,241,234,${p.t})`;
    ctx.lineWidth = 2*dpr;
    ctx.beginPath(); ctx.arc(p.x, p.y, (1-p.t)*260*dpr, 0, 6.28); ctx.stroke();
    p.t -= .012;
  });
  if (!reduce) requestAnimationFrame(frame);
}
if (reduce) { ctx.fillStyle='#07080d'; ctx.fillRect(0,0,w,h); frame(); }
else requestAnimationFrame(frame);
</script>
</body>
</html>
